#!/bin/sh
# SPDX-License-Identifier: Apache-2.0
# Test suite for om/tls/rev.om. Usage: sh om/tls/test/rev/run.sh OMC
# Builds om2 + sha2 hkdf ec rsa x509 rev + driver.om into build/tls/rev/, runs vectors/cases.txt
# (generated by gen_rev.py with python cryptography; real/ holds a real Let's Encrypt CRL and its
# issuer), cross-checks every OCSP response and CRL verdict class with openssl where it can, and runs
# the source mutants. Exit 0 only when everything passes; final line "REV PASS cases=N mutants=M/M".
set -eu
omc=${1:?usage: run.sh OMC}
here=$(cd "$(dirname "$0")" && pwd)
tls=$(cd "$here/../.." && pwd)
root=$(cd "$tls/../.." && pwd)
pin=$(sed -n 's/^OMC_PIN=//p' "$root/om/units.sh")
out="$root/build/tls/rev"
vec="$here/vectors"
mkdir -p "$out"
bad=0
say() { printf '%s\n' "$*"; }
fail() { say "FAIL $*"; bad=1; }
run() { nice -n 19 ionice -c3 "$@"; }

[ "$(sha256sum < "$omc" | cut -c1-64)" = "$pin" ] || { say "FAIL omc is not the pinned compiler"; exit 1; }

# build LIB DRIVER BIN
build() {
	{ echo om2; cat "$tls/sha2.om" "$tls/hkdf.om" "$tls/ec.om" "$tls/rsa.om" "$tls/x509.om" "$1" "$2"; } > "$3.om"
	if ! run "$omc" < "$3.om" > "$3" 2> "$3.err" || [ -s "$3.err" ]; then
		say "omc refused $3.om: $(cat "$3.err")"
		return 1
	fi
	chmod +x "$3"
}

build "$tls/rev.om" "$here/driver.om" "$out/driver" || { say "REV FAIL build"; exit 1; }
say "omc     sha256 $pin"
say "library sha256 $(sha256sum < "$tls/rev.om" | cut -c1-64) ($(grep -c '^fn ' "$tls/rev.om") functions)"
say "driver  sha256 $(sha256sum < "$out/driver" | cut -c1-64)"
cp "$vec/cases.txt" "$out/cases.txt"
ncase=$(grep -c '^[OUIHAE] ' "$out/cases.txt")

# drive FILE BIN NAME -> sets rc, last
drive() {
	set +e
	(cd "$vec" && run "$2" < "$1") > "$out/$3.out" 2>&1
	rc=$?
	set -e
	last=$(tail -n 1 "$out/$3.out")
}

drive "$out/cases.txt" "$out/driver" main
checks=$(printf '%s\n' "$last" | awk '$1 == "rev" && $2 == "driver:" && $4 == "checks," && $5 == "0" && $6 == "failed" { print $3 }')
if [ "$rc" -eq 0 ] && [ -n "$checks" ]; then
	say "PASS cases.txt: $last"
	grep '^fuzz ' "$out/main.out" | sed 's/^/PASS /'
else
	fail "cases.txt: exit $rc: $(grep -E 'MISMATCH|driver' "$out/main.out" | head -n 20 | tr '\n' ' ')"
fi

# oracle: openssl agrees with the generated OCSP status classes (good / revoked / unknown) and with
# the CRL signature verdicts, so the expectations are not only gen_rev.py's word
oracle=0
oraclen=0
if command -v openssl > /dev/null 2>&1; then
	pem() { openssl x509 -inform DER -in "$vec/$1" -out "$out/$2.pem"; }
	pem pki/iss.der iss
	pem pki/root.der root
	pem real/ye2.der ye2
	for c in good:good revoked:revoked unknown:unknown deleg:good deleg_revoked:revoked; do
		f=${c%%:*}; want=${c#*:}
		oraclen=$((oraclen + 1))
		got=$(openssl ocsp -respin "$vec/pki/o_$f.der" -issuer "$out/iss.pem" -cert "$vec/pki/leaf.der" -VAfile "$out/iss.pem" -no_nonce -CAfile "$out/root.pem" -attime 1793059200 2>/dev/null | awk -F': ' '$1 ~ /leaf.der$/ { print $2; exit }') || true
		if [ "$got" = "$want" ]; then oracle=$((oracle + 1)); else fail "openssl ocsp $f: got '$got' want '$want'"; fi
	done
	# openssl crl exits 0 even on "verify failure", so the verdict is its "verify OK" line
	for c in revoked:0 clean:0 bad_sig:1 root_signed:1; do
		f=${c%%:*}; want=${c#*:}
		oraclen=$((oraclen + 1))
		if openssl crl -inform DER -in "$vec/pki/c_$f.der" -CAfile "$out/iss.pem" -noout 2>&1 | grep -qx 'verify OK'; then got=0; else got=1; fi
		if [ "$got" = "$want" ]; then oracle=$((oracle + 1)); else fail "openssl crl $f: verify exit $got want $want"; fi
	done
	oraclen=$((oraclen + 1))
	if openssl crl -inform DER -in "$vec/real/ye2-74.crl" -CAfile "$out/ye2.pem" -noout 2>&1 | grep -qx 'verify OK' \
		&& openssl crl -inform DER -in "$vec/real/ye2-74.crl" -noout -text | grep -q '050A72B7AE90C2E1C61BB7D1568032F79549'; then
		oracle=$((oracle + 1))
	else
		fail "openssl: real CRL signature or listed serial"
	fi
	say "PASS openssl oracle $oracle/$oraclen"
fi

# mutants: each must make the driver finish with exit 1 and MISMATCH lines (or trap)
mut=0
mutok=0
mutant() {
	mut=$((mut + 1))
	sed "$1" "$tls/rev.om" > "$out/mut-$2-lib.om"
	if cmp -s "$tls/rev.om" "$out/mut-$2-lib.om"; then fail "mutant $2: sed changed nothing"; return; fi
	if ! build "$out/mut-$2-lib.om" "$here/driver.om" "$out/mut-$2"; then fail "mutant $2: build"; return; fi
	drive "$out/cases.txt" "$out/mut-$2" "mut-$2"
	n=$(grep -c '^MISMATCH ' "$out/mut-$2.out" || true)
	if [ "$rc" -eq 1 ] && [ "$n" -gt 0 ] && printf '%s\n' "$last" | grep -q "^rev driver: [0-9]* checks, $n failed$"; then
		mutok=$((mutok + 1))
		say "PASS mutant $2 detected ($n MISMATCH: $(grep '^MISMATCH ' "$out/mut-$2.out" | head -n 2 | cut -d' ' -f4 | tr '\n' ' '))"
	elif [ "$rc" -ge 100 ]; then
		mutok=$((mutok + 1))
		say "PASS mutant $2 detected (driver trapped, exit $rc, after $n MISMATCH)"
	else
		fail "mutant $2 not detected: exit $rc: $last"
	fi
}
# freshness: nextUpdate in the past accepted
mutant 's/^if le get o 18 nw$/if lt get o 18 0/' fresh-next-update
# freshness: thisUpdate in the future accepted (skew unbounded)
mutant 's/^if gt get o 17 add nw RVSKEW$/if gt get o 17 add nw 99999999/' fresh-skew
# signature: OCSP and CRL signatures not checked
mutant 's/^ret chain_sig d kd part w 0 mul X5RSZ 2$/ret 0/' signature-skipped
# CertID: serial bytes not compared
mutant 's/^if ne get d add a i get t add RVSER i$/if eq i 999999/' serial-bytes
# CertID: issuer key hash not compared
mutant 's/^if ne get d add s i get t add q i$/if eq i 999999/' certid-hash
# certStatus ignored (everything good)
mutant 's/^put o 16 v$/put o 16 0/' cert-status
# must-staple ignored
mutant 's/^ret RVENOST$/ret 0/' must-staple
# delegated responder: OCSPSigning EKU not required
mutant 's/^if ne rev_ocspeku c part w 0 X5RSZ 0$/if eq rev_ocspeku c part w 0 X5RSZ 9/' responder-eku
# delegated responder: not required to be issued by the leaf's issuer
mutant 's/^if ne chain_link c is part w 0 64 0$/if eq chain_link c is part w 0 64 99/' responder-issuer
# delegated responder: validity not checked
mutant 's/^if ne chain_time part w 0 X5RSZ get o 0 0$/if eq chain_time part w 0 X5RSZ get o 0 99/' responder-validity
# CRL: issuer Name not compared
mutant 's/^if not der_same part cr get o 28 get o 29 /if and false not der_same part cr get o 28 get o 29 /' crl-issuer-name
# CRL: issuer keyUsage cRLSign not required
mutant 's/^if eq and get w add X5RSZ X5RKUB 2 0$/if eq and get w add X5RSZ X5RKUB 2 9/' crl-sign-ku
# CRL: issuingDistributionPoint not matched against the leaf
mutant 's/^v = rev_dpmatch part b get p 7 get p 8 lb w o$/v = ulong 0/' crl-idp-scope
# CRL: delta and indirect CRL extensions not refused
mutant 's/^if or eq o 11 eq o 15$/if eq o 99/' crl-delta-indirect
# CRL: listed serial ignored
mutant 's/^ret RVEREV$/ret 0/' revoked-verdict
# SHA-1 round constant
mutant 's/^ret 0x8f1bbcdc$/ret 0x8f1bbcdd/' sha1-constant
# expectation mutant: one expected code changed
mut=$((mut + 1))
sed 's/^O ocsp_good X509_OK /O ocsp_good REV_ERR_STALE /' "$out/cases.txt" > "$out/mut-expect.txt"
drive "$out/mut-expect.txt" "$out/driver" mut-expect
if [ "$rc" -eq 1 ] && printf '%s\n' "$last" | grep -q '^rev driver: [0-9]* checks, 1 failed$' && grep -q '^MISMATCH .* ocsp_good ' "$out/mut-expect.out"; then
	mutok=$((mutok + 1))
	say "PASS mutant expectation detected"
else
	fail "expectation mutant not detected: exit $rc: $last"
fi

say "driver checks=${checks:-0}"
if [ "$bad" -ne 0 ]; then
	say "REV FAIL cases=$ncase mutants=$mutok/$mut"
	exit 1
fi
say "REV PASS cases=$ncase mutants=$mutok/$mut"
